23	// isolationState 构造一份带非零时间片、多角色多物品且排列固定的完整状态。
24	// hero 携带 gold=1、key=3（总量 4，贴在 5 的上限内），mage 携带 gold=2
25	// （恰好等于上限 2），另有一个规则未设携带上限的 rogue。
26	func isolationState() State {
27		return State{
28			Seed:  4242,
29			Rules: isolationRules(),
30			Time:  7,
31			Characters: []Character{
32				{ID: "hero", Location: "hall", Items: []CharacterItem{
33					{Item: "gold", Count: 1},
34					{Item: "key", Count: 3},
35				}},
36				{ID: "mage", Location: "yard", Items: []CharacterItem{
37					{Item: "gold", Count: 2},
38				}},
39				{ID: "rogue", Location: "cave", Items: []CharacterItem{
40					{Item: "gold", Count: 100},
41				}},
42			},
43		}
44	}
45	
46	// TestWorldFromStateCopiesFullContents 重建成功后，地图种子、非零时间片、
47	// 完整规则以及角色和物品的内容与排列都与来源一致。
48	func TestWorldFromStateCopiesFullContents(t *testing.T) {
49		src := isolationState()
50		w, err := WorldFromState(src)
51		if err != nil {
52			t.Fatalf("WorldFromState: %v", err)
53		}
54		got := w.Snapshot()
55	
56		if got.Seed != 4242 || got.Time != 7 {
57			t.Fatalf("种子/时间片未保留: %+v", got)
58		}
59		if got.Rules.Version != "v1" {
60			t.Fatalf("规则版本错误: %q", got.Rules.Version)
61		}
62		if !reflect.DeepEqual(got.Rules.Locations, []string{"hall", "yard", "cave"}) {
63			t.Fatalf("地点内容/排列错误: %v", got.Rules.Locations)
64		}
65		if !reflect.DeepEqual(got.Rules.Edges, []Edge{
66			{From: "hall", To: "yard"},
67			{From: "yard", To: "cave"},
68		}) {
69			t.Fatalf("道路内容/排列错误: %+v", got.Rules.Edges)
70		}
71		if !reflect.DeepEqual(got.Rules.ItemKinds, []string{"gold", "key"}) {
72			t.Fatalf("物品种类/排列错误: %v", got.Rules.ItemKinds)
73		}
74		if !reflect.DeepEqual(got.Rules.CarryLimits, map[string]int{"hero": 5, "mage": 2}) {
75			t.Fatalf("携带上限错误: %+v", got.Rules.CarryLimits)
76		}
77		wantChars := src.Characters
78		if !reflect.DeepEqual(got.Characters, wantChars) {
79			t.Fatalf("角色/物品的内容与排列未保留:\n got %+v\nwant %+v", got.Characters, wantChars)
80		}
81	}
82	
83	// TestWorldFromStateSourceMutationsIsolated 调用方把读档状态交给
84	// WorldFromState 后，再去修改来源里规则的地点列表、道路端点、物品种类、
85	// 携带上限，以及角色位置与携带物品的名称、数量，都不应改变重建出的世界；
86	// 世界继续按重建时保存的道路、允许物品和携带上限判断提交成败。
87	func TestWorldFromStateSourceMutationsIsolated(t *testing.T) {
88		src := isolationState()
89		w, err := WorldFromState(src)
90		if err != nil {
91			t.Fatalf("WorldFromState: %v", err)
92		}
93	
94		// 改动来源：删掉一个地点、删掉重建世界仍需要的道路 yard-cave、删掉
95		// key 种类、把 hero 上限提到 9，并改角色位置与物品名称/数量。
96		src.Rules.Locations = src.Rules.Locations[:2]
97		src.Rules.Edges[1] = Edge{From: "hall", To: "hall"} // 去掉 yard-cave
98		src.Rules.ItemKinds = src.Rules.ItemKinds[:1]       // 去掉 key
99		src.Rules.CarryLimits["hero"] = 9
100		src.Characters[0].Location = "cave"
101		src.Characters[0].Items[0].Item = "stone"
102		src.Characters[0].Items[0].Count = 88
103		src.Characters[0].Items[1].Count = 88
104	
105		// 世界快照仍保留创建时的完整内容。
106		got := w.Snapshot()
107		if !reflect.DeepEqual(got.Rules, isolationRules()) {
108			t.Fatalf("来源的规则修改泄漏进世界: %+v", got.Rules)
109		}
110		if !reflect.DeepEqual(got.Characters, isolationState().Characters) {
111			t.Fatalf("来源的角色/物品修改泄漏进世界: %+v", got.Characters)
112		}
113	
114		// 来源已删除的道路 yard-cave 在重建世界中仍可使用（hero 在 hall，
115		// 先 hall->yard 再 yard->cave），且时间从重建时的 7 向前推进。
116		if _, err := w.Apply(Commit{
117			Moves: []Move{{Character: "hero", To: "yard"}},
118			Time:  8,
119		}); err != nil {
120			t.Fatalf("重建世界应保留 hall-yard 道路: %v", err)
121		}
122		if _, err := w.Apply(Commit{
123			Moves: []Move{{Character: "hero", To: "cave"}},
124			Time:  9,
125		}); err != nil {
126			t.Fatalf("来源删除的 yard-cave 道路仍应可用: %v", err)
127		}
128	
129		// 来源已删除的物品种类 key 在世界中仍被允许。
130		if _, err := w.Apply(Commit{
131			ItemChanges: []ItemChange{{Character: "hero", Item: "key", Delta: 1}},
132			Time:        10,
133		}); err != nil {
134			t.Fatalf("重建世界应继续允许来源已删除的物品种类 key: %v", err)
135		}
136	
137		// hero 当前总量 5（1 gold + 4 key），重建时上限为 5：再加 1 个 gold
138		// 总量到 6 必须失败，即便来源把上限提高到了 9。
139		if _, err := w.Apply(Commit{
140			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
141			Time:        11,
142		}); err == nil {
143			t.Fatal("来源提高携带上限后，原本超限的提交不应成功")
144		} else {
145			mustRuleError(t, err, "hero", "上限")
146		}
147		// 失败提交未推动时间，世界仍停在时间片 10、hero 仍在 cave。
148		snap := w.Snapshot()
149		if snap.Time != 10 || snap.Characters[0].Location != "cave" {
150			t.Fatalf("被上限拒绝后世界状态异常: %+v", snap)
151		}
152	
153		// 移动合法性同样按重建时的地点集合判断：来源删掉 cave 不影响世界。
154		if _, err := w.Apply(Commit{
155			Moves: []Move{{Character: "hero", To: "yard"}},
156			Time:  11,
157		}); err != nil {
158			t.Fatalf("重建世界应保留 cave 地点: %v", err)
159		}
160	}
161	
162	// TestWorldFromStateTwoRebuildsIndependent 从同一份合法状态连续重建两个
163	// 世界：在其中一个里成功移动、改变物品并推进时间，另一个世界以及来源
164	// 状态都保持原来的完整内容。
165	func TestWorldFromStateTwoRebuildsIndependent(t *testing.T) {
166		src := isolationState()
167		original := isolationState()
168	
169		w1, err := WorldFromState(src)
170		if err != nil {
171			t.Fatalf("重建 w1 失败: %v", err)
172		}
173		w2, err := WorldFromState(src)
174		if err != nil {
175			t.Fatalf("重建 w2 失败: %v", err)
176		}
177	
178		// 在 w1 中移动、增减物品并推进时间。hero 起始总量 4（gold1+key3），
179		// gold +1 后总量恰好贴上重建时的上限 5。
180		if _, err := w1.Apply(Commit{
181			Moves: []Move{
182				{Character: "hero", To: "yard"},
183				{Character: "hero", To: "cave"},
184			},
185			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
186			Time:        12,
187		}); err != nil {
188			t.Fatalf("w1 提交失败: %v", err)
189		}
190		s1 := w1.Snapshot()
191		if s1.Time != 12 || s1.Characters[0].Location != "cave" {
192			t.Fatalf("w1 提交结果错误: %+v", s1)
193		}
194		if got := s1.Characters[0].Items[0]; got != (CharacterItem{Item: "gold", Count: 2}) {
195			t.Fatalf("w1 物品数量错误: %+v", got)
196		}
197	
198		// w2 仍是重建时的完整内容。
199		s2 := w2.Snapshot()
200		if !reflect.DeepEqual(s2, original) {
201			t.Fatalf("w2 受 w1 操作影响:\n got %+v\nwant %+v", s2, original)
202		}
203		// 来源状态同样纹丝不动。
204		if !reflect.DeepEqual(src, original) {
205			t.Fatalf("来源状态受重建世界操作影响:\n got %+v\nwant %+v", src, original)
206		}
207	
208		// w2 仍可独立地按自己的时间片（7）继续：倒退到 w1 的更早目标应失败，
209		// 而沿自己保存的道路移动成功。
210		if _, err := w2.Apply(Commit{Time: 6}); err == nil {
211			t.Fatal("w2 不应受 w1 影响而允许时间倒退")
212		}
213		if _, err := w2.Apply(Commit{
214			Moves: []Move{{Character: "hero", To: "yard"}},
215			Time:  13,
216		}); err != nil {
217			t.Fatalf("w2 独立移动失败: %v", err)
218		}
219	}
220	
221	// TestWorldFromStateReturnedStatesAreDetached 调用方拿到重建世界的快照、或
222	// 一次成功提交返回的状态后，即使深度修改其中的道路、携带上限、角色和
223	// 物品，也不改变该世界后续的状态和规则判断。
224	func TestWorldFromStateReturnedStatesAreDetached(t *testing.T) {
225		src := isolationState()
226		w, err := WorldFromState(src)
227		if err != nil {
228			t.Fatalf("WorldFromState: %v", err)
229		}
230	
231		// 1) 篡改 Snapshot 返回值。
232		snap := w.Snapshot()
233		snap.Rules.Edges = nil
234		snap.Rules.CarryLimits["hero"] = 1000
235		snap.Rules.Locations = append(snap.Rules.Locations, "moon")
236		snap.Rules.ItemKinds = append(snap.Rules.ItemKinds, "stone")
237		snap.Characters[0].Location = "cave"
238		snap.Characters[0].Items[0].Count = 999
239	
240		// 2) 做一次成功提交并篡改其返回状态：返回状态声称 hero 已在 cave 且
241		// gold 很多、上限很高。
242		out, err := w.Apply(Commit{
243			Moves:       []Move{{Character: "hero", To: "yard"}},
244			ItemChanges: []ItemChange{{Character: "hero", Item: "key", Delta: 1}},
245			Time:        8,
246		})
247		if err != nil {
248			t.Fatalf("成功提交失败: %v", err)
249		}
250		out.Rules.Edges = nil
251		out.Rules.CarryLimits["hero"] = 1000
252		out.Characters[0].Location = "hall"
253		out.Characters[0].Items[1].Count = 99
254	
255		// 世界内部仍以提交后的真实状态为准：hero 在 yard（不是返回状态里的
256		// hall），gold=1 key=4 总量 5 贴上 hero 上限 5。
257		cur := w.Snapshot()
258		if cur.Time != 8 || cur.Characters[0].Location != "yard" {
259			t.Fatalf("世界内部状态被返回值篡改污染: %+v", cur)
260		}
261		if !reflect.DeepEqual(cur.Characters[0].Items, []CharacterItem{
262			{Item: "gold", Count: 1},
263			{Item: "key", Count: 4},
264		}) {
265			t.Fatalf("世界内部物品被返回值篡改: %+v", cur.Characters[0].Items)
266		}
267		if !reflect.DeepEqual(cur.Rules, isolationRules()) {
268			t.Fatalf("世界内部规则被返回值篡改: %+v", cur.Rules)
269		}
270	
271		// 后续规则判断仍按世界内部的道路与上限：
272		// yard->cave 道路仍在（返回值把 Edges 置空不应生效），移动成功。
273		if _, err := w.Apply(Commit{
274			Moves: []Move{{Character: "hero", To: "cave"}},
275			Time:  9,
276		}); err != nil {
277			t.Fatalf("世界内部道路应仍可用: %v", err)
278		}
279		// 上限仍为 5，当前总量 5：再 +1 gold 到 6 必须失败（返回值声称 1000
280		// 不应生效）。
281		if _, err := w.Apply(Commit{
282			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
283			Time:        10,
284		}); err == nil {
285			t.Fatal("世界应仍按原携带上限拒绝超限提交")
286		} else {
287			mustRuleError(t, err, "hero", "上限")
288		}
289		// 被拒绝的提交连时间都不推进。
290		if got := w.Snapshot().Time; got != 9 {
291			t.Fatalf("超限失败后时间不应推进，得到 %d", got)
292		}
293	}
294	
295	// TestWorldFromStateFailedCommitLeavesAllUntouched 一次提交包含合法移动，
296	// 却因物品超出携带上限而整体失败：重建世界停在提交前，来源状态与从同一
297	// 状态重建的另一个世界都不受影响。
298	func TestWorldFromStateFailedCommitLeavesAllUntouched(t *testing.T) {
299		src := isolationState()
300		original := isolationState()
301		w1, err := WorldFromState(src)
302		if err != nil {
303			t.Fatalf("重建 w1 失败: %v", err)
304		}
305		w2, err := WorldFromState(src)
306		if err != nil {
307			t.Fatalf("重建 w2 失败: %v", err)
308		}
309		before := w1.Snapshot()
310	
311		// hero 在 hall，hall->yard 是合法移动；但 gold 1->7（总量 10）超过
312		// hero 上限 5，整次提交必须失败。
313		if _, err := w1.Apply(Commit{
314			Moves:       []Move{{Character: "hero", To: "yard"}},
315			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 6}},
316			Time:        8,
317		}); err == nil {
318			t.Fatal("合法移动 + 超限物品的提交应整体失败")
319		} else {
320			mustRuleError(t, err, "hero", "上限")
321		}
322	
323		// w1 完全停在提交前（位置、物品、时间都不变）。
324		if after := w1.Snapshot(); !reflect.DeepEqual(after, before) {
325			t.Fatalf("失败提交改变了重建世界:\n before %+v\n after  %+v", before, after)
326		}
327		// 失败后仍可在提交前状态上重试一次合法提交，证明世界没有被污染。
328		if _, err := w1.Apply(Commit{
329			Moves:       []Move{{Character: "hero", To: "yard"}},
330			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
331			Time:        8,
332		}); err != nil {
333			t.Fatalf("回滚后重试合法提交应成功: %v", err)
334		}
335		// w2 与来源状态仍是原始完整内容。
336		if got := w2.Snapshot(); !reflect.DeepEqual(got, original) {
337			t.Fatalf("另一个重建世界受失败提交影响: %+v", got)
338		}
339		if !reflect.DeepEqual(src, original) {
340			t.Fatalf("来源状态受失败提交影响: %+v", src)
341		}
342	}
343	
344	// TestWorldFromStateKeepsZeroQuantityItem 角色带有数量为零的物品是合法
345	// 状态：重建后该条目仍保留在原位置（既不丢失也不重排），后续增减照常
346	// 生效。
347	func TestWorldFromStateKeepsZeroQuantityItem(t *testing.T) {
348		src := State{
349			Seed:  5,
350			Rules: isolationRules(),
351			Time:  3,
352			Characters: []Character{
353				{ID: "hero", Location: "hall", Items: []CharacterItem{
354					{Item: "gold", Count: 0},
355					{Item: "key", Count: 2},
356				}},
357				{ID: "mage", Location: "yard"},
358			},
359		}
360		w, err := WorldFromState(src)
361		if err != nil {
362			t.Fatalf("含零数量物品的状态重建不应失败: %v", err)
363		}
364		got := w.Snapshot()
365		want := []CharacterItem{{Item: "gold", Count: 0}, {Item: "key", Count: 2}}
366		if !reflect.DeepEqual(got.Characters[0].Items, want) {
367			t.Fatalf("零数量条目应保留在原位置: %+v", got.Characters[0].Items)
368		}
369	
370		// 对零数量条目增减照常生效：+3 后位于原位且数量为 3。
371		out, err := w.Apply(Commit{
372			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 3}},
373			Time:        4,
374		})
375		if err != nil {
376			t.Fatalf("对零数量物品增加应成功: %v", err)
377		}
378		if !reflect.DeepEqual(out.Characters[0].Items, []CharacterItem{
379			{Item: "gold", Count: 3},
380			{Item: "key", Count: 2},
381		}) {
382			t.Fatalf("增减后物品内容/排列错误: %+v", out.Characters[0].Items)
383		}
384		// 再减回 0：条目仍保留，不被移除。
385		out2, err := w.Apply(Commit{
386			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: -3}},
387			Time:        5,
388		})
389		if err != nil {
390			t.Fatalf("减回零应成功: %v", err)
391		}
392		if !reflect.DeepEqual(out2.Characters[0].Items, want) {
393			t.Fatalf("减回零后条目应保留在原位置: %+v", out2.Characters[0].Items)
394		}
395		// 继续减到负数则按既有规则失败并整体回滚。
396		if _, err := w.Apply(Commit{
397			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: -1}},
398			Time:        6,
399		}); err == nil {
400			t.Fatal("零数量再减应失败")
401		} else {
402			mustRuleError(t, err, "hero", "gold")
403		}
404		if cur := w.Snapshot(); !reflect.DeepEqual(cur.Characters[0].Items, want) || cur.Time != 5 {
405			t.Fatalf("失败提交后状态异常: %+v", cur)
406		}
407	}
408	
409	// TestWorldFromStateCharacterWithoutCarryLimit 规则没有为某角色设置携带
410	// 上限时，即使其携带总量超过其他角色的上限，重建也应成功并继续允许其
411	// 携带这么多（以及继续增加）；而设了上限的角色仍照常受限。
412	func TestWorldFromStateCharacterWithoutCarryLimit(t *testing.T) {
413		src := State{
414			Seed:  9,
415			Rules: isolationRules(), // hero 上限 5、mage 上限 2、rogue 无上限
416			Time:  1,
417			Characters: []Character{
418				{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 5}}},
419				{ID: "rogue", Location: "cave", Items: []CharacterItem{
420					{Item: "gold", Count: 50},
421					{Item: "key", Count: 50},
422				}},
423			},
424		}
425		w, err := WorldFromState(src)
426		if err != nil {
427			t.Fatalf("无上限角色携带大量物品应允许重建: %v", err)
428		}
429	
430		// rogue 总量 100，远超 hero 的上限 5，但重建后继续增加仍被允许。
431		out, err := w.Apply(Commit{
432			ItemChanges: []ItemChange{{Character: "rogue", Item: "gold", Delta: 100}},
433			Time:        2,
434		})
435		if err != nil {
436			t.Fatalf("无上限角色应能继续增加物品: %v", err)
437		}
438		if !reflect.DeepEqual(out.Characters[1].Items, []CharacterItem{
439			{Item: "gold", Count: 150},
440			{Item: "key", Count: 50},
441		}) {
442			t.Fatalf("无上限角色物品数量错误: %+v", out.Characters[1].Items)
443		}
444	
445		// 设了上限的 hero 仍照常受限：5->6 必须失败。
446		if _, err := w.Apply(Commit{
447			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
448			Time:        3,
449		}); err == nil {
450			t.Fatal("有上限的 hero 超限应失败")
451		} else {
452			mustRuleError(t, err, "hero", "上限")
453		}
454		if cur := w.Snapshot(); cur.Time != 2 || cur.Characters[0].Items[0].Count != 5 {
455			t.Fatalf("hero 失败提交不应改变世界: %+v", cur)
456		}
457	}
