1	package world
2	
3	import (
4		"testing"
5	)
6	
7	func baseRules() Rules {
8		return Rules{
9			Version:   "v1",
10			Locations: []string{"hall", "yard", "cave"},
11			Edges: []Edge{
12				{From: "hall", To: "yard"},
13				{From: "yard", To: "cave"},
14			},
15			ItemKinds:   []string{"gold", "key"},
16			CarryLimits: map[string]int{"hero": 5, "mage": 2},
17		}
18	}
19	
20	func baseWorld(t *testing.T) *World {
21		t.Helper()
22		w, err := NewWorld(InitialData{
23			Seed:  42,
24			Rules: baseRules(),
25			Characters: []Character{
26				{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
27				{ID: "mage", Location: "yard"},
28			},
29		})
30		if err != nil {
31			t.Fatalf("NewWorld: %v", err)
32		}
33		return w
34	}
35	
36	func TestNewWorldValidation(t *testing.T) {
37		cases := []struct {
38			name string
39			mod  func(*InitialData)
40		}{
41			{"空规则版本", func(d *InitialData) { d.Rules.Version = "" }},
42			{"地点重复", func(d *InitialData) { d.Rules.Locations = []string{"a", "a"} }},
43			{"连通引用缺失地点", func(d *InitialData) { d.Rules.Edges = []Edge{{From: "a", To: "zzz"}} }},
44			{"物品种类重复", func(d *InitialData) { d.Rules.ItemKinds = []string{"gold", "gold"} }},
45			{"携带上限为负", func(d *InitialData) { d.Rules.CarryLimits["hero"] = -1 }},
46			{"角色标识重复", func(d *InitialData) {
47				d.Characters = append(d.Characters, Character{ID: "hero", Location: "hall"})
48			}},
49			{"角色在不存在地点", func(d *InitialData) { d.Characters[0].Location = "void" }},
50			{"非法物品", func(d *InitialData) {
51				d.Characters[0].Items = []CharacterItem{{Item: "rock", Count: 1}}
52			}},
53			{"物品数量为负", func(d *InitialData) {
54				d.Characters[0].Items = []CharacterItem{{Item: "gold", Count: -1}}
55			}},
56			{"超过携带上限", func(d *InitialData) {
57				d.Characters[0].Items = []CharacterItem{{Item: "gold", Count: 6}}
58			}},
59		}
60		for _, tc := range cases {
61			t.Run(tc.name, func(t *testing.T) {
62				data := InitialData{
63					Seed:       42,
64					Rules:      baseRules(),
65					Characters: []Character{{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}}},
66				}
67				tc.mod(&data)
68				if _, err := NewWorld(data); err == nil {
69					t.Fatal("期望建立世界失败，但成功了")
70				} else if _, ok := err.(*RuleError); !ok {
71					t.Fatalf("期望 *RuleError，得到 %T", err)
72				}
73			})
74		}
75	}
76	
77	func TestTimeStartsAtZero(t *testing.T) {
78		w := baseWorld(t)
79		if got := w.Snapshot().Time; got != 0 {
80			t.Fatalf("初始时间片应为 0，得到 %d", got)
81		}
82	}
83	
84	func TestApplySuccessAndIsolation(t *testing.T) {
85		w := baseWorld(t)
86		st, err := w.Apply(Commit{
87			Moves:       []Move{{Character: "hero", To: "yard"}},
88			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 2}},
89			Time:        3,
90		})
91		if err != nil {
92			t.Fatalf("Apply: %v", err)
93		}
94		if st.Time != 3 || st.Characters[0].Location != "yard" {
95			t.Fatalf("提交结果不符: %+v", st)
96		}
97		// 修改返回状态不得影响世界。
98		st.Characters[0].Location = "cave"
99		st.Rules.Version = "hacked"
100		again := w.Snapshot()
101		if again.Characters[0].Location != "yard" || again.Rules.Version != "v1" {
102			t.Fatal("返回状态被修改后影响到了世界")
103		}
104	}
105	
106	func TestApplyRollback(t *testing.T) {
107		cases := []struct {
108			name string
109			c    Commit
110		}{
111			{"时间倒退", Commit{Time: -1}},
112			{"角色不存在", Commit{Moves: []Move{{Character: "ghost", To: "yard"}}, Time: 1}},
113			{"地点不存在", Commit{Moves: []Move{{Character: "hero", To: "void"}}, Time: 1}},
114			{"移动无连通", Commit{Moves: []Move{{Character: "hero", To: "cave"}}, Time: 1}},
115			{"物品角色不存在", Commit{ItemChanges: []ItemChange{{Character: "x", Item: "gold"}}, Time: 1}},
116			{"物品种类不存在", Commit{ItemChanges: []ItemChange{{Character: "hero", Item: "rock"}}, Time: 1}},
117			{"数量变负", Commit{ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: -5}}, Time: 1}},
118			{"超上限", Commit{
119				ItemChanges: []ItemChange{{Character: "hero", Item: "key", Delta: 6}}, Time: 1,
120			}},
121			{"多项中一项非法", Commit{
122				Moves:       []Move{{Character: "hero", To: "yard"}},
123				ItemChanges: []ItemChange{{Character: "mage", Item: "gold", Delta: 9}},
124				Time:        2,
125			}},
126		}
127		for _, tc := range cases {
128			t.Run(tc.name, func(t *testing.T) {
