	final, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("最终", final.State)

	// Output:
	// 新建: time=0 hero@village wood=2 ore=1
	// 准备: time=4 hero@forest wood=3 ore=1
